 1	// RUN: /compile:0 /nologo
 2	
 3	method CardinalitySubsetLt<T>(A: set<T>, B: set<T>)
 4	  requires A < B
 5	  ensures |A| < |B|
 6	  decreases B
 7	{
 8	  var b :| b in B && b !in A;
 9	  var B' := B - {b};
10	  assert |B| == |B'| + 1;
11	  if A < B' {
12	    CardinalitySubsetLt(A, B');
13	  } else {
14	    assert A == B';
15	  }
16	}
17	
18	method strategy<T>(P: set<T>, Special: T) returns (count: int)
19	  requires |P| > 0 && Special in P
20	  ensures count == |P| - 1
21	  decreases *
22	{
23	  count := 0;
24	  var I := {};
25	  var S := {};
26	  var switch := false;
27	
28	  while count < |P| - 1
29	    invariant count <= |P| - 1
30	    invariant count > 0 ==> Special in I
31	    invariant Special !in S && S < P && S <= I <= P
32	    invariant if switch then |S| == count + 1 else |S| == count
33	    decreases *
34	  { 
35	    var p :| p in P;
36	    I := I + {p};
37	
38	    if p == Special {
39	      if switch {
40	        switch := false;
41	        count := count + 1;
42	      }
43	    } else {
44	      if p !in S && !switch {
45	        S := S + {p};
46	        switch := true;
47	      }
48	    }
49	  }  
50	
51	  CardinalitySubsetLt(S, I);
52	
53	  if I < P {
54	    CardinalitySubsetLt(I, P);
55	  }
56	  assert P <= I;
57	
58	  assert I == P;
59	}
60

